"""Self-contained web interface served by the existing FastAPI application."""
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter()

PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>SuperChat</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#19382e;background:#f3f6f2;font-size:15px}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{cursor:pointer;border:1px solid #cfddd2;background:white;border-radius:10px;padding:9px 13px;color:#254d3d}button:hover{background:#edf4ee}button:disabled{opacity:.5;cursor:wait}header{padding:20px 5%;display:flex;align-items:center;justify-content:space-between;background:white;border-bottom:1px solid #dce5dc}h1{font-size:23px;margin:0}header p{font-size:12px;margin:5px 0;color:#6b7b71}.mark{display:inline-grid;place-items:center;background:#275d44;color:white;width:34px;height:34px;border-radius:11px;margin-right:8px}main{max-width:1250px;margin:auto;display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:22px;padding:24px}.chat{min-width:0;background:white;border:1px solid #dce5dc;border-radius:18px;overflow:hidden;display:flex;flex-direction:column;height:calc(100dvh - 145px);min-height:450px}#messages{overflow:auto;flex:1;padding:25px}.welcome{padding:25px 0}.welcome h2{font-size:29px;font-weight:600;margin:0 0 10px}.muted{color:#6b7b71;font-size:13px;line-height:1.6}.examples{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}.message{margin:0 0 22px;max-width:100%;line-height:1.6;overflow-wrap:anywhere}.message.user{margin-left:15%;background:#e8f2e8;border-radius:14px;padding:12px 16px}.label{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#718177;margin-bottom:5px}.text{white-space:pre-wrap}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:9px;margin-top:12px}.card{border:1px solid #dce5dc;border-radius:12px;padding:13px;font-size:13px;background:#fcfdfb}.card strong{display:block;margin-bottom:6px}.card .meta{white-space:pre-line;color:#617267}.card button{margin:9px 5px 0 0;font-size:12px;padding:6px 9px}.tag{display:inline-block;background:#edf3ed;font-size:10px;border-radius:20px;padding:2px 9px;margin-bottom:8px}form{display:flex;gap:8px;padding:14px;border-top:1px solid #e3eae1}input{width:100%;min-width:0;padding:12px;border:1px solid #ccdace;border-radius:11px;outline-color:#275d44}form button{background:#275d44;color:white;border:0;padding:10px 22px}aside section{background:white;border:1px solid #dce5dc;border-radius:15px;padding:18px;margin-bottom:14px}aside h2{font-size:15px;margin:0 0 12px}.sideitem{padding:10px 0;border-bottom:1px solid #edf1eb;font-size:12px;overflow-wrap:anywhere}.error{color:#a33535;font-size:13px;padding:0 16px}#status{font-size:12px;color:#617267}details{margin-top:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}#total{font-weight:600;margin-top:12px}@media(max-width:800px){main{grid-template-columns:1fr;padding:12px}.chat{height:70dvh}aside{display:grid;grid-template-columns:1fr 1fr;gap:10px}header{padding:15px}header p{max-width:240px}.cards{grid-template-columns:1fr}}@media(max-width:440px){aside{grid-template-columns:1fr}.welcome h2{font-size:24px}}
</style></head><body>
<header><div><h1><span class="mark">S</span>SuperChat</h1><p>Flights, shopping and cinema. One conversation.</p></div><button id="new">New conversation</button></header>
<main><div class="chat"><div id="messages" role="log" aria-live="polite"></div><div id="status" style="padding:0 16px" role="status">Connecting…</div><div id="error" class="error" role="alert"></div><form id="form"><input id="input" maxlength="2000" aria-label="Your message" placeholder="Ask about a flight, a product or a movie…" autocomplete="off"><button id="send" type="submit">Send</button></form></div>
<aside><section><h2>Your cart</h2><div id="cart" class="muted">Loading…</div><div id="total"></div></section><section><h2>Reservations</h2><div id="bookings" class="muted">Loading…</div></section><section><h2>Phase 1 demo</h2><div class="muted">Official mock data · AZN<br>Reference date: 2 November 2026<br>Reservations are simulated.<br>No payments are collected.</div></section></aside></main>
<script>
'use strict';
const $=id=>document.getElementById(id);let sid=null,busy=false;
const money=n=>Number(n).toFixed(2)+' AZN';
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let d;try{d=await r.json();}catch{throw Error('The server returned an invalid response.');}if(!r.ok){const e=Error(d.message||(typeof d.detail==='string'?d.detail:'Request failed. Please check your input.'));e.status=r.status;throw e;}return d;}
function action(parent,label,fn){const b=node('button',label);b.type='button';b.disabled=busy;b.onclick=()=>guard(fn);parent.append(b);return b;}
function setBusy(value){busy=value;document.querySelectorAll('button').forEach(b=>b.disabled=value);$('input').disabled=value;}
async function guard(fn){if(busy)return;setBusy(true);$('error').textContent='';try{await fn();}catch(e){$('error').textContent=e.message;}finally{setBusy(false);$('input').focus();}}
function welcome(){const w=node('div',undefined,'welcome');w.append(node('h2','What would you like to explore?'),node('p','Find your next flight, compare products or plan a movie night.','muted'));const examples=node('div',undefined,'examples');for(const text of ['Flights from Baku to Istanbul on Friday','Wireless headphones under 100 AZN','What is playing tonight?'])action(examples,text,()=>send(text));w.append(examples);$('messages').append(w);}
function card(item){const e=node('div',undefined,'card');const p=item.product||item;const id=p.id||p.record_id||p.reservation_id||'';const title=p.name?.en||p.title||p.movie_title||(p.flight_number?`${p.origin.city} → ${p.destination.city}`:p.name)||id;e.append(node('strong',title));let lines=[id];if(p.price_azn!==undefined)lines.push(money(p.price_azn));if(p.departure_local)lines.push(`${p.airline} · ${p.departure_local.replace('T',' ')}`,`${p.duration_min} min · ${p.stops===0?'Direct':p.stops+' stop(s)'} · Baggage ${p.baggage_kg} kg`);if(p.stock!==undefined)lines.push(`${p.brand} · ${p.color}`,`Stock: ${p.stock} · Rating ${p.rating}/5`);if(p.movie_title)lines.push(p.cinema_name,`${p.date} · ${p.time}`,`Seats: ${p.seats_available}`);else if(p.genre)lines.push(p.genre.join(', '),`${p.language} · Rating ${p.rating}/10`);if(p.status)lines.push(p.status,`Quantity: ${p.quantity}`,`Total: ${money(p.total_azn)}`);e.append(node('div',lines.filter(Boolean).join('\n'),'meta'));
if(/^P\d+$/.test(id)){action(e,'Add to cart',async()=>{await api(`/api/sessions/${sid}/cart/${id}`,{method:'PUT',body:JSON.stringify({quantity:1})});await refresh();});}
if(/^F\d+$/.test(id)||/^S\d+$/.test(id)){action(e,'Reserve',async()=>{const raw=prompt('How many seats?','1');if(raw===null)return;const quantity=Number(raw);if(!Number.isInteger(quantity)||quantity<1)throw Error('Enter a positive whole number.');if(!confirm(`Confirm mock reservation: ${quantity} seat(s) for ${id}?`))return;const booking=await api(`/api/sessions/${sid}/reservations`,{method:'POST',body:JSON.stringify({domain:id[0]==='F'?'flights':'showtimes',record_id:id,quantity,request_key:crypto.randomUUID()})});render({role:'assistant',message:'Mock reservation confirmed.',results:[{domain:'Reservation',items:[booking]}]});await refresh();});}
const detail=node('details');detail.append(node('summary','All details'),node('pre',JSON.stringify(p,null,2)));e.append(detail);return e;}
function render(turn){const e=node('div',undefined,'message '+turn.role);e.append(node('div',turn.role==='user'?'You':`SuperChat${turn.category?' · '+turn.category:''}`,'label'),node('div',turn.content||turn.message||'','text'));for(const result of turn.results||[]){e.append(node('span',result.domain,'tag'));const cards=node('div',undefined,'cards');for(const item of result.items||[])cards.append(card(item));e.append(cards);}$('messages').append(e);$('messages').scrollTop=$('messages').scrollHeight;}
async function refresh(){const [cart,bookings]=await Promise.all([api(`/api/sessions/${sid}/cart`),api(`/api/sessions/${sid}/reservations`)]);$('cart').replaceChildren();$('total').textContent=money(cart.total_azn);if(!cart.items.length)$('cart').textContent='Your cart is empty.';for(const item of cart.items){const e=node('div',`${item.product.name.en} × ${item.quantity} · ${money(item.subtotal_azn)}`,'sideitem');action(e,'Remove',async()=>{await api(`/api/sessions/${sid}/cart/${item.product.id}`,{method:'DELETE'});await refresh();});$('cart').append(e);}$('bookings').replaceChildren();if(!bookings.length)$('bookings').textContent='No reservations yet.';for(const b of bookings)$('bookings').append(node('div',`${b.record_id} · ${b.quantity} seat(s) · ${money(b.total_azn)}\n${b.reservation_id}`,'sideitem'));}
async function start(fresh=false){sid=fresh?null:localStorage.getItem('superchat-session');if(sid){try{const history=await api(`/api/sessions/${sid}/history`);$('messages').replaceChildren();if(history.length)history.forEach(render);else welcome();}catch(e){if(e.status!==404)throw e;sid=null;}}if(!sid){sid=(await api('/api/sessions',{method:'POST'})).session_id;localStorage.setItem('superchat-session',sid);$('messages').replaceChildren();welcome();}await refresh();$('status').textContent='Ready · English demo';}
async function send(text){if(!text.trim())return;render({role:'user',content:text});$('input').value='';$('status').textContent='Working…';try{const result=await api(`/api/sessions/${sid}/chat`,{method:'POST',body:JSON.stringify({message:text})});render({role:'assistant',...result});await refresh();}finally{$('status').textContent='Ready · English demo';}}
$('form').onsubmit=e=>{e.preventDefault();guard(()=>send($('input').value));};$('new').onclick=()=>guard(()=>start(true));guard(()=>start()).catch(()=>{});
</script></body></html>'''


@router.get('/', response_class=HTMLResponse, include_in_schema=False)
def home():
    return HTMLResponse(PAGE)
